import{_ as e,o as t,c as r,at as o}from"./chunks/framework.CY22Hent.js";const i="/assets/ruankao_2026-08-29_004131_245.imz-0gfs.png",S=JSON.parse('{"title":"系统分析师笔记21_信息物理系统分析与设计","description":"","frontmatter":{"title":"系统分析师笔记21_信息物理系统分析与设计","date":"2026-08-28T00:00:00.000Z","lastUpdated":"2026-08-28T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/系统分析师笔记21_信息物理系统分析与设计.md","filePath":"blogs/软考/系统分析师笔记21_信息物理系统分析与设计.md"}'),l={name:"blogs/软考/系统分析师笔记21_信息物理系统分析与设计.md"};function h(n,a,s,p,d,P){return t(),r("div",null,[...a[0]||(a[0]=[o('<p>[toc]</p><h1 id="系统分析师笔记21-信息物理系统分析与设计" tabindex="-1">系统分析师笔记21_信息物理系统分析与设计 <a class="header-anchor" href="#系统分析师笔记21-信息物理系统分析与设计" aria-label="Permalink to &quot;系统分析师笔记21_信息物理系统分析与设计&quot;">​</a></h1><p>该笔记内容来自《系统分析师教程》第2版。</p><h2 id="信息物理系统概述" tabindex="-1">信息物理系统概述 <a class="header-anchor" href="#信息物理系统概述" aria-label="Permalink to &quot;信息物理系统概述&quot;">​</a></h2><p>随着互联网的迅猛发展，物联网IoT(Internet of Things)愈来愈深入人类社会工作生活的方方面面。IoT，顾名思义，即万物相连的互联网，是互联网的延伸和扩展，是将各种信息传感设备与网络结合起来而形成的一个更大网络，实现任何时间、任何地点，人、机、物的互联互通。</p><p>信息物理系统或赛博物理系统(Cyber-Physical System，CPS)作为物联网的演进，引起了国内外相关科研机构、政府部门和社会的广泛关注。尤其是《中国制造2025》指出，基于CPS的智能装备、智能工厂等智能制造正在引领制造方式变革，要围绕控制系统、工业软件、工业网络、工业云服务和工业大数据平台等，加强CPS研发与应用。</p><p>可见，物联网、CPS系统正在人类社会工业化和信息化演进过程中发挥着愈来愈重要的作用。</p><h3 id="物联网-iot-简介" tabindex="-1">物联网（IoT）简介 <a class="header-anchor" href="#物联网-iot-简介" aria-label="Permalink to &quot;物联网（IoT）简介&quot;">​</a></h3><p>物联网(IoT)是新一代信息技术的重要组成部分，物联网的核心和基础仍然是互联网，其用户端延伸和扩展到了更广泛的物理实体，满足它们之间信息交换和通信的需求。</p><p>因此，物联网也可以说是，通过射频识别、红外感应器、全球定位系统、激光扫描器等信息传感设备，按约定协议将任何物理实体与互联网相连接，满足彼此之间信息交换和通信的要求，以达到对物理实体的智能化识别、定位、跟踪、监控和管理目的的一种网络。</p><p>例如，通过各种传感器等装置与技术，实时采集任何需要监控、互动的物体或过程的信息，如声、光、热、电、力学、化学、生物、位置等信息，再通过各类可能的网络进行信息传递，实现物与物、物与人的信息互通，以及对物和过程的智能化感知、识别和管理。</p><h3 id="赛博物理系统-cps-简介" tabindex="-1">赛博物理系统（CPS）简介 <a class="header-anchor" href="#赛博物理系统-cps-简介" aria-label="Permalink to &quot;赛博物理系统（CPS）简介&quot;">​</a></h3><p>CPS是将计算资源与物理资源紧密结合的产物，CPS的影响将远远超越20世纪的IT革命，就像Internet改变了人与人交互的方式一样，CPS的出现改变了人与物理世界交互的方式。</p><p>CPS是一个涉及计算、网络和物理实体的复杂系统，通过3C技术使得它们有机融合与深度协作，通过人机交互接口与物理实体交互，使信息空间以远程、可靠、实时、安全、智能化、协作的方式操控一个物理实体。</p><p>也就是说，CPS通过集成先进的感知、计算、通信、控制等信息技术和自动控制技术，构建了物理空间与信息空间中人、机、物、环境、信息等要素相互映射、实时交互、高效协同的复杂系统，实现系统内资源配置和运行的按需响应、快速迭代、动态优化。</p><h3 id="cps与物联网关系" tabindex="-1">CPS与物联网关系 <a class="header-anchor" href="#cps与物联网关系" aria-label="Permalink to &quot;CPS与物联网关系&quot;">​</a></h3><p>CPS与物联网有类似的能力，但CPS更强调循环反馈，要求系统能够在感知物理世界之后通过通信与计算再对物理世界起到反馈控制作用。</p><p>物联网可以看作CPS的一种简约应用，或者说，CPS让物联网的定义和概念明晰起来。</p><h2 id="信息物理系统架构" tabindex="-1">信息物理系统架构 <a class="header-anchor" href="#信息物理系统架构" aria-label="Permalink to &quot;信息物理系统架构&quot;">​</a></h2><h3 id="cps分层架构" tabindex="-1">CPS分层架构 <a class="header-anchor" href="#cps分层架构" aria-label="Permalink to &quot;CPS分层架构&quot;">​</a></h3><p>CPS 可划分三级，即单元级、系统级、系统之系统级(System of Systems,SoS)。它们之间是一种递进、扩展关系。</p><ul><li>单元级CPS可通过组合与集成，如通过CPS总线等互连成为更高级CPS(即系统级CPS)。</li><li>系统级CPS可通过工业云、工业大数据等平台构建成SoS级CPS(即系统之系统级CPS)，以提供如企业级层面的数字化运营等服务。</li></ul><p>CPS系统三级模型如图21-2所示。 <img src="'+i+'" alt="ruankao_2026-08-29_004131_245.png" loading="lazy"></p><h3 id="cps典型系统构成" tabindex="-1">CPS典型系统构成 <a class="header-anchor" href="#cps典型系统构成" aria-label="Permalink to &quot;CPS典型系统构成&quot;">​</a></h3><p>通常CPS由一些基本功能单元组成，这些基本功能单元包括传感器(Sensor)、执行器(Actuator)和决策控制单元(Decision-making Control Unit)等。</p><ul><li>传感器是一种嵌入式设备，能够监测、感知外界信号、物理条件(如光、热)或化学组成(如烟雾等);</li><li>执行器是一种嵌入式设备，能够接收控制指令并对受控对象施加控制作用;</li><li>决策控制单元是一种逻辑控制设备，能够根据用户定义的语义规则生成控制逻辑。</li></ul><h2 id="信息物理系统技术框架" tabindex="-1">信息物理系统技术框架 <a class="header-anchor" href="#信息物理系统技术框架" aria-label="Permalink to &quot;信息物理系统技术框架&quot;">​</a></h2><h3 id="cps核心技术" tabindex="-1">CPS核心技术 <a class="header-anchor" href="#cps核心技术" aria-label="Permalink to &quot;CPS核心技术&quot;">​</a></h3><p>总体来说，CPS包含四大方面核心技术，即感知和自动控制、工业软件、工业网络、工业云和智能服务平台相关技术。</p><ul><li>(1)感知和自动控制。感知和自动控制是CPS实现的硬件支撑。其主要有智能感知技术和虚实融合控制技术。</li><li>(2)工业软件。工业软件固化了CPS计算和数据流程的规则，是CPS的核心。其主要涉及嵌入式软件技术、MBD技术、CAX/MES/ERP软件技术等。</li><li>(3)工业网络。工业网络是工业监测和控制数据等在人、机、物之间传输的网络载体，其采用的接入技术主要有现场总线技术、工业以太网技术、无线技术、SDN等。</li><li>(4)工业云和智能服务平台。工业云和智能服务平台是CPS数据汇聚和支撑上层应用解决方案的基础，对外提供资源管控和能力服务。其采用的主要技术有边缘计算技术、雾计算技术、大数据分析技术等。</li></ul><h2 id="信息物理系统开发技术" tabindex="-1">信息物理系统开发技术 <a class="header-anchor" href="#信息物理系统开发技术" aria-label="Permalink to &quot;信息物理系统开发技术&quot;">​</a></h2><h3 id="感知和控制相关技术" tabindex="-1">感知和控制相关技术 <a class="header-anchor" href="#感知和控制相关技术" aria-label="Permalink to &quot;感知和控制相关技术&quot;">​</a></h3><p>CPS使用到的感知和自动控制技术主要包括智能感知技术和虚实融合控制技术。</p><h3 id="工业软件相关技术" tabindex="-1">工业软件相关技术 <a class="header-anchor" href="#工业软件相关技术" aria-label="Permalink to &quot;工业软件相关技术&quot;">​</a></h3><p>工业软件是指专用于工业领域，为提高工业企业研发、制造、生产、服务与管理水平以及工业产品使用价值的软件。</p><p>CPS涉及的工业软件技术主要有嵌入式软件技术、MBD技术、CAX/MES/ERP软件技术等。</p><h3 id="网络相关技术" tabindex="-1">网络相关技术 <a class="header-anchor" href="#网络相关技术" aria-label="Permalink to &quot;网络相关技术&quot;">​</a></h3><p>CPS网络的实现，在接入技术上，主要采用有线网络(如现场总线技术和工业以太网技术)、无线网络和基于有线无线网络形成的柔性灵活的工厂网络;</p><p>从网络类型来分，既有各种智能设备组成的专用协议局域网，也有基于通用TCP/IP的公共互联网。</p><h3 id="服务平台相关技术" tabindex="-1">服务平台相关技术 <a class="header-anchor" href="#服务平台相关技术" aria-label="Permalink to &quot;服务平台相关技术&quot;">​</a></h3><p>服务平台通过边缘计算技术、雾计算技术、大数据分析技术等进行数据加工处理，形成对外提供数据服务的能力，并在数据服务基础上提供个性化和专业化智能服务。</p><h2 id="控制系统与网络通信" tabindex="-1">控制系统与网络通信 <a class="header-anchor" href="#控制系统与网络通信" aria-label="Permalink to &quot;控制系统与网络通信&quot;">​</a></h2><p>在CPS系统中，自动控制无处不在。而控制过程的执行，往往又离不开通信的支撑。</p><p>由前面介绍可知，CPS系统是一种包含由物理部件、计算部件等构成的交互网络的系统。</p><p>为CPS应用控制行为提供的通信服务，往往需要是超可靠、高可用的，在某些情况下，甚至是超低端到端时延的，如智能制造、智能电网、能源自动化等领域。</p><h2 id="cps应用分析与设计" tabindex="-1">CPS应用分析与设计 <a class="header-anchor" href="#cps应用分析与设计" aria-label="Permalink to &quot;CPS应用分析与设计&quot;">​</a></h2><h3 id="工业设计系统" tabindex="-1">工业设计系统 <a class="header-anchor" href="#工业设计系统" aria-label="Permalink to &quot;工业设计系统&quot;">​</a></h3><h3 id="生产制造系统" tabindex="-1">生产制造系统 <a class="header-anchor" href="#生产制造系统" aria-label="Permalink to &quot;生产制造系统&quot;">​</a></h3><h3 id="产品服务系统" tabindex="-1">产品服务系统 <a class="header-anchor" href="#产品服务系统" aria-label="Permalink to &quot;产品服务系统&quot;">​</a></h3><h3 id="产业链协同系统" tabindex="-1">产业链协同系统 <a class="header-anchor" href="#产业链协同系统" aria-label="Permalink to &quot;产业链协同系统&quot;">​</a></h3>',50)])])}const u=e(l,[["render",h]]);export{S as __pageData,u as default};
